import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The gauntlet — what a minted law must survive","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/explanation/the-gauntlet.md","filePath":"vendored/graphopt/explanation/the-gauntlet.md"}`),a={name:`graphopt/explanation/the-gauntlet.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="the-gauntlet-—-what-a-minted-law-must-survive" tabindex="-1">The gauntlet — what a minted law must survive <a class="header-anchor" href="#the-gauntlet-—-what-a-minted-law-must-survive" aria-label="Permalink to “The gauntlet — what a minted law must survive”">​</a></h1><p>A candidate law is <em>proposed</em> cheaply and <em>admitted</em> expensively. The admission gauntlet is the pipeline every minted law runs before it may enter <code>DEFAULT</code> — and the reason the shipped bank can be trusted without trusting the proposer.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>propose → numeric oracle → derivability check → typed-pay gate</span></span>
<span class="line"><span>        → adversarial sweep → certificate replay → MACHINE_SHIPPED</span></span></code></pre></div><h2 id="the-stages" tabindex="-1">The stages <a class="header-anchor" href="#the-stages" aria-label="Permalink to “The stages”">​</a></h2><ol><li><strong>Numeric oracle.</strong> Both sides of the candidate equality execute on real tensors (seeded fixtures, fp64) and must agree — equality is tested, not assumed.</li><li><strong>Derivability check.</strong> <code>verify_law(lhs, rhs, rules)</code> puts both sides in a fresh small e-graph and saturates under the known laws — the e-graph <em>is</em> the decision procedure for e-class membership. On a merge it emits a positional certificate and replays it on real terms; the certificate is tried in both directions so a witness is a genuine derivation, never a trusted stub.</li><li><strong>The typed-pay gate.</strong> The candidate must actually pay: measured wall/peak cost on the fixtures, under the <a href="./three-costs.html">three-costs</a> discipline — <code>dag_cost</code> ranking is never enough.</li><li><strong>The adversarial sweep.</strong> <code>mlopt_discovery.gap_gen</code> generates bindings the corpus cannot — witnesses inside the guard&#39;s <em>false region</em> — and tries to falsify the candidate&#39;s side conditions. This is where the teeth are: the sweep killed <strong>212 bad accepts</strong> on <code>mul_unsq_nat</code>&#39;s first (plain broadcast-equality) guard, caught four false twins, and found a real lowering bug no test covered.</li><li><strong>Certificate + provenance.</strong> The survivor ships in <code>DEFAULT</code> with <code>MACHINE_SHIPPED</code> provenance — replayable at import, auditable via <code>law_provenance(rule)</code>.</li></ol><h2 id="the-worked-example-—-mul-unsq-nat" tabindex="-1">The worked example — <code>mul_unsq_nat</code> <a class="header-anchor" href="#the-worked-example-—-mul-unsq-nat" aria-label="Permalink to “The worked example — mul_unsq_nat”">​</a></h2><p>The first law minted from a <em>corpus op-tuple</em> rather than a hand-declared need. The census saw <code>mul(unsqueeze, unsqueeze)</code> in a real model&#39;s <code>β_t·k_t</code> write; the candidate <code>mul(unsqueeze U d, unsqueeze V d) = unsqueeze(mul U V, d)</code> was proposed; <code>auto_cond</code>&#39;s first guard was <strong>falsified by the sweep</strong> (212 bad accepts); the exact <code>flat-map-unsq</code> guard was synthesized instead — 0 bad accepts, 0 misses; it pays −12.27% on its source workload and ships in <code>DEFAULT</code>. Its apparent sibling (<code>mul_unsqueeze_r_id</code>) was <em>correctly rejected</em> — its real sites are semantically unequal, and the guard declines all of them.</p><h2 id="the-referee-contract" tabindex="-1">The referee contract <a class="header-anchor" href="#the-referee-contract" aria-label="Permalink to “The referee contract”">​</a></h2><p>The gauntlet emits a plain <code>{axis: value}</code> measurement; the <a href="./the-game.html#the-referee-seam"><code>ScoringSpec</code></a> on the game side turns it into a verdict — <code>score(spec, measured)</code> returns gates cleared, the weighted value, and the axes the measurement lacked. The two sides meet only through that mapping: measurement code never imports the scoring module, and the scoring module imports no measurement machinery.</p><h2 id="the-honest-boundary" tabindex="-1">The honest boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The honest boundary”">​</a></h2><p>Admission is <em>regime-bounded</em>: fixtures are small, seeded, one hardware box. The gauntlet&#39;s job is to make the claim <em>falsifiable and bounded</em>, not universal — a law that pays on its fixtures and replays its certificate ships; the scope of &quot;pays&quot; is part of the record.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};